);

// Негативные тесты, для которых не требуется обновление токена
const negativeRequests = [
    "Bag without Authorization",
    "Bag with Invalid Token"
];

// Пропускаем автоматическое обновление для указанных запросов
const skipAuthRefresh = negativeRequests.includes(
    pm.info.requestName
);

// Не обновляем токен перед OAuth-запросом
// и специально изолированными негативными тестами
if (!isTokenRequest && !skipAuthRefresh) {

    const token = pm.collectionVariables.get("token");

    const expiresAt = Number(
        pm.collectionVariables.get("token_expires_at") || 0
    );

    // Проверяем, существует ли действующий токен
    const tokenIsValid =
        typeof token === "string" &&
        token.length > 0 &&
        Number.isFinite(expiresAt) &&
        Date.now() < expiresAt;

    if (tokenIsValid) {

        console.log("Using existing Guest Token");

    } else {

        console.log(
            "Guest token is missing or expired. Refreshing..."
        );

        
const basicAuth = await pm.vault.get(
    "ae_basic_auth"
);

if (
    typeof basicAuth !== "string" ||
    !/^Basic\s+[A-Za-z0-9+/=]+$/.test(basicAuth.trim())
) {
    throw new Error(
        "Basic Authentication credentials are missing or invalid in Postman Vault"
    );
}

console.log("Basic authorization format verified");


        // Запрашиваем новый Guest Token
        const tokenResponse = await pm.sendRequest({
            url: tokenEndpoint,
            method: "POST",

            header: {
                "Authorization": basicAuth.trim(),
                "Content-Type": "application/x-www-form-urlencoded",
                "Accept": "application/vnd.oracle.resource+json",
                "aelang": "en_US",
                "aesite": "AEO_US",
                "aecountry": "US",
                "Origin": "https://www.ae.com",
                "Referer": "https://www.ae.com/us/en"
            },

            body: {
                mode: "urlencoded",
                urlencoded: [
                    {
                        key: "grant_type",
                        value: "client_credentials"
                    }
                ]
            }
        });

        if (!tokenResponse || tokenResponse.code !== 200) {
            throw new Error(
                "Failed to refresh Guest Token. HTTP status: " +
                (tokenResponse ? tokenResponse.code : "No response")
            );
        }

        const data = tokenResponse.json();

        if (
            !data ||
            typeof data.access_token !== "string" ||
            data.access_token.length === 0
        ) {
            throw new Error(
                "Access token is missing in OAuth response"
            );
        }

        const expiresIn = Number(data.expires_in ?? 1800);

        if (!Number.isFinite(expiresIn) || expiresIn <= 0) {
            throw new Error("Invalid token expiration time");
        }

        // Сохраняем новый токен
        pm.collectionVariables.set(
            "token",
            data.access_token
        );

        // Время истечения с запасом 60 секунд
        const expiresAtNew =
            Date.now() +
            Math.max(0, expiresIn - 60) * 1000;

        pm.collectionVariables.set(
            "token_expires_at",
            String(expiresAtNew)
        );

        console.log(
            "Guest Token refreshed successfully"
        );
    }
} else if (skipAuthRefresh) {

    console.log(
        "Automatic token refresh skipped for negative test"
    );
